const minimum = Number($('Attendance Settings').first().json.minimumAttendance || 75);
const warning = Number($('Attendance Settings').first().json.warningAttendance || 85);
const output = [];

for (const item of $input.all()) {
  const f = item.json.fields || item.json;
  const name = f.Name || f.name || f.Student || f.student || 'Unknown Student';
  const totalClasses = Number(f['Total Classes'] ?? f.totalClasses ?? f.Total ?? 0);
  const attendedClasses = Number(f['Attended Classes'] ?? f.attendedClasses ?? f.Attended ?? 0);
  let attendance = totalClasses > 0 ? Number(((attendedClasses / totalClasses) * 100).toFixed(2)) : Number(f.Attendance || 0);
  let status = attendance < minimum ? 'CRITICAL' : attendance < warning ? 'WARNING' : 'GOOD';
  let priority = status === 'CRITICAL' ? 'HIGH' : status === 'WARNING' ? 'MEDIUM' : 'LOW';
  let classesNeeded = 0;
  if (totalClasses > 0 && attendance < minimum) {
    let n = 0;
    while (((attendedClasses + n) / (totalClasses + n)) * 100 < minimum && n < 10000) n++;
    classesNeeded = n;
  }
  output.push({json: {
    recordId: item.json.id || '',
    studentName: name,
    totalClasses,
    attendedClasses,
    attendancePercentage: attendance,
    minimumRequired: minimum,
    warningThreshold: warning,
    status,
    priority,
    classesNeededToReachMinimum: classesNeeded
  }});
}
return output;

const records = $input.all().map(i => i.json);
const critical = records.filter(r => r.status === 'CRITICAL');
const warning = records.filter(r => r.status === 'WARNING');
const good = records.filter(r => r.status === 'GOOD');
const report = [
  '# Attendance Intelligence Report',
  '',
  `Total Students: ${records.length}`,
  `Good Attendance: ${good.length}`,
  `Warning: ${warning.length}`,
  `Critical: ${critical.length}`,
  '',
  '## Critical Students',
  critical.length ? critical.map(r => `- **${r.studentName}**: ${r.attendancePercentage}% — needs ${r.classesNeededToReachMinimum} consecutive attended class(es) to reach the minimum`).join('\n') : '- None',
  '',
  '## Warning Students',
  warning.length ? warning.map(r => `- **${r.studentName}**: ${r.attendancePercentage}%`).join('\n') : '- None',
  '',
  '## All Students',
  records.length ? records.map(r => `- ${r.studentName}: ${r.attendancePercentage}% — ${r.status}`).join('\n') : '- No records found'
].join('\n');
return [{json: {reportDate: new Date().toISOString(), totalStudents: records.length, criticalCount: critical.length, warningCount: warning.length, goodCount: good.length, criticalStudents: critical, warningStudents: warning, goodStudents: good, report}}];

const r = $json;
const message = `Attendance Intelligence Report

Date: ${r.reportDate}
Total Students: ${r.totalStudents}

GOOD: ${r.goodCount}
WARNING: ${r.warningCount}
CRITICAL: ${r.criticalCount}

${r.criticalStudents.length ? 'Critical Students:\n' + r.criticalStudents.map(s => `• ${s.studentName}: ${s.attendancePercentage}%`).join('\n') : 'No critical students.'}

${r.warningStudents.length ? '\nWarning Students:\n' + r.warningStudents.map(s => `• ${s.studentName}: ${s.attendancePercentage}%`).join('\n') : ''}`;
return [{json: {...r, summaryMessage: message}}];
